      "answer": "<div style='background-color:#f0f8ff; padding:15px; border-left:5px solid #16a085; border-radius:8px;'><p><strong>ઉકેલ/જવાબ:</strong> પાઈ (π) અથવા કુદરતી લઘુગુણકનો આધાર (e).</p><hr><p style='color:#d32f2f; font-weight:bold;'>💡 નિતેશ સરની શોર્ટકટ ટ્રીક: શુદ્ધ આંકડાઓને કોઈ પરિમાણ હોતા નથી.</p></div>"
